  function materialLinksFor(type,id){return (project()?.materialLinks||[]).filter(link=>link.targetType===type&&link.targetId===id);}
  function materialLinkTitle(link){
    const r=resource(link.resourceId);if(r?.title)return r.title;
    for(const plan of project()?.plans||[])for(const figure of plan.figures||[]){
      const panel=figure.panels.find(item=>item.id===link.resourceId);if(panel)return panel.title;
      const block=(figure.evidenceBlocks||[]).find(item=>item.id===link.resourceId);if(block)return block.title;
    }
    return link.resourceId;
  }
  function materialMarkShape(link,index){
    const fill=link.stance==='support'?'#7fb1dd':link.stance==='oppose'?'#d98b86':'#b9bab1';
    const type=link.materialType;
    const base=`<g transform="translate(${index*11},0)"><title>${U(materialLinkTitle(link))} · ${link.stance==='support'?'支持':link.stance==='oppose'?'反对':'待判断'}${link.note?'：'+E(link.note):''}</title>`;
    if(type==='figure')return base+`<rect x="1" y="1" width="8" height="8" transform="rotate(45 5 5)" fill="${fill}" stroke="#fff" stroke-width="1"/></g>`;
    if(type==='panel')return base+`<circle cx="5" cy="5" r="4.3" fill="${fill}" stroke="#fff" stroke-width="1"/></g>`;
    if(type==='evidence-block')return base+`<polygon points="1,5 3.5,1 7,1 9.5,5 7,9 3.5,9" fill="${fill}" stroke="#fff" stroke-width="1"/></g>`;
    return base+`<rect x="1" y="1" width="8" height="8" fill="${fill}" stroke="#fff" stroke-width="1"/></g>`;
  }
  function materialMarksMarkup(links,x,y,key){if(!links.length)return '';const visible=links.slice(0,6),width=visible.length*11+2;return `<g class="material-marks" data-material-marks="${E(key)}" transform="translate(${x},${y})"><rect class="material-marks-bg" x="-2" y="-2" width="${width}" height="14" rx="7"/>${visible.map(materialMarkShape).join('')}</g>`;}
