    if(key!==ui.scopeKey){ui.scopeKey=key;ui.view=sc?M.clone(session.entityView(sc)):{zoom:1,x:80,y:80,selection:[]};ui.view.zoom=M.finite(ui.view.zoom,1)||1;ui.view.selection||=[];ui.story=s.mode==='figure'&&(ui.view.mode||plan()?.view?.mode)==='story';}
