    document.querySelectorAll('[data-action="mode-radar"],[data-action="mode-library"],[data-action="mode-hypothesis"],[data-action="mode-figure"]').forEach(b=>b.classList.toggle('active',b.dataset.action===(ui.library?'mode-library':ui.radar?'mode-radar':'mode-'+s.mode)));
    document.querySelector('[data-action="undo"]').disabled=!session.state.undo.length||!!session.state.proposal;
    document.querySelector('[data-action="redo"]').disabled=!session.state.redo.length||!!session.state.proposal;
