      const keys=(row.figures||[]).flatMap(figure=>(figure.panels||[]).flatMap(panel=>(panel.links||[]).filter(link=>link.hypothesisId).map(link=>projection.localKey(project().id,'hypothesis',link.hypothesisId))));
